garO(){return"\u0641\u0626\u0627\u062a \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0627\u062a"},
gaqX(){return"\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a"},
garf(){return"\u0645\u062d\u0648\u0651\u0644\u0629 \u0644\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629"},
